// Cost estimates  (permissions: estimate.view, estimate.prepare, estimate.explain)
export const listEstimates = () =>
  api("GET", `/cost-estimates`, undefined);   // api(): see get_guide('envelope-and-errors')

// One cost estimate  (permissions: estimate.view, estimate.prepare, estimate.explain)
export const getEstimate = (estimate_id) =>
  api("GET", `/cost-estimates/${estimate_id}`, undefined);   // api(): see get_guide('envelope-and-errors')

// Record that the estimate was explained  (permissions: estimate.explain)
export const explain = (estimate_id, body) =>
  api("POST", `/cost-estimates/${estimate_id}/explain`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// The estimate to print and sign (A4)  (permissions: estimate.view, estimate.prepare, estimate.explain)
export const printEstimate = (estimate_id) =>
  api("GET", `/cost-estimates/${estimate_id}/print-payload`, undefined);   // api(): see get_guide('envelope-and-errors')

// Estimates to explain: new admissions and changes of ward  (permissions: estimate.view, estimate.prepare, estimate.explain)
export const worklistCostEstimates = () =>
  api("GET", `/cost-estimates/worklist`, undefined);   // api(): see get_guide('envelope-and-errors')
